import {
    previewSitePackageParamsSchema,
    publicSitePackageParamsSchema,
    publishedSitePackageParamsSchema,
    siteContentCacheBusterQuerySchema,
    sitePackageIdParamsSchema,
    sitePackageRevisionParamsSchema
} from '@imsweb/contracts/site-packages';
import { adminApiPath, apiPath, siteContentPath, sitesPath } from '@imsweb/contracts/paths';
import type { ImsHonoApp } from '@/app';
import {
    handleCreateSitePackage,
    handleCreateSitePackageRevision,
    handleDeleteSitePackageRevision,
    handleListSitePackages,
    handlePublishSitePackageRevision,
    handleRotateSitePackagePreviewToken
} from '@/domains/delivery/site-packages/handlers/manage-site-packages';
import {
    handleGetPublicSitePackage,
    handleServePublishedSitePackageShell,
    handleServePreviewSitePackage,
    handleServePublishedSitePackage
} from '@/domains/delivery/site-packages/handlers/serve-site-package';
import {
    validatePreviewSitePackageParams,
    validatePublicSitePackageParams,
    validatePublishedSitePackageParams,
    validateSitePackageIdParams,
    validateSitePackageRevisionParams
} from '@/domains/delivery/site-packages/request';
import { backofficeAuth, backofficeCsrf, opOnly } from '@/middleware/hono-auth';
import {
    paramSchemaValidator,
    querySchemaValidator
} from '@/middleware/request-validation';

const sitePackageIdValidator = paramSchemaValidator(
    sitePackageIdParamsSchema,
    {},
    validateSitePackageIdParams
);
const sitePackageRevisionValidator = paramSchemaValidator(
    sitePackageRevisionParamsSchema,
    {},
    validateSitePackageRevisionParams
);
const publicSitePackageValidator = paramSchemaValidator(
    publicSitePackageParamsSchema,
    {},
    validatePublicSitePackageParams
);
const publishedSitePackageValidator = paramSchemaValidator(
    publishedSitePackageParamsSchema,
    {},
    validatePublishedSitePackageParams
);
const previewSitePackageValidator = paramSchemaValidator(
    previewSitePackageParamsSchema,
    {},
    validatePreviewSitePackageParams
);
const siteContentCacheBusterValidator = querySchemaValidator(
    siteContentCacheBusterQuerySchema
);

export function registerSitePackageRoutes(app: ImsHonoApp): void {
    app.get(
        apiPath('/site-packages/:slug'),
        publicSitePackageValidator,
        handleGetPublicSitePackage
    );
    app.get(adminApiPath('/site-packages'), backofficeAuth, opOnly, handleListSitePackages);
    app.post(
        adminApiPath('/site-packages'),
        backofficeAuth,
        opOnly,
        backofficeCsrf,
        handleCreateSitePackage
    );
    app.post(
        adminApiPath('/site-packages/:id/revisions'),
        backofficeAuth,
        opOnly,
        backofficeCsrf,
        sitePackageIdValidator,
        handleCreateSitePackageRevision
    );
    app.post(
        adminApiPath('/site-packages/:id/revisions/:revisionId/publish'),
        backofficeAuth,
        opOnly,
        backofficeCsrf,
        sitePackageRevisionValidator,
        handlePublishSitePackageRevision
    );
    app.post(
        adminApiPath('/site-packages/:id/revisions/:revisionId/preview-token'),
        backofficeAuth,
        opOnly,
        backofficeCsrf,
        sitePackageRevisionValidator,
        handleRotateSitePackagePreviewToken
    );
    app.delete(
        adminApiPath('/site-packages/:id/revisions/:revisionId'),
        backofficeAuth,
        opOnly,
        backofficeCsrf,
        sitePackageRevisionValidator,
        handleDeleteSitePackageRevision
    );

    app.on(
        ['GET', 'HEAD'],
        sitesPath('/:slug'),
        publicSitePackageValidator,
        handleServePublishedSitePackageShell
    );
    app.on(
        ['GET', 'HEAD'],
        sitesPath('/:slug/'),
        publicSitePackageValidator,
        handleServePublishedSitePackageShell
    );
    app.on(
        ['GET', 'HEAD'],
        siteContentPath('/_preview/:previewToken'),
        previewSitePackageValidator,
        siteContentCacheBusterValidator,
        handleServePreviewSitePackage
    );
    app.on(
        ['GET', 'HEAD'],
        siteContentPath('/_preview/:previewToken/*'),
        previewSitePackageValidator,
        siteContentCacheBusterValidator,
        handleServePreviewSitePackage
    );
    app.on(
        ['GET', 'HEAD'],
        siteContentPath('/:slug/:revisionId'),
        publishedSitePackageValidator,
        siteContentCacheBusterValidator,
        handleServePublishedSitePackage
    );
    app.on(
        ['GET', 'HEAD'],
        siteContentPath('/:slug/:revisionId/*'),
        publishedSitePackageValidator,
        siteContentCacheBusterValidator,
        handleServePublishedSitePackage
    );
}
